DROP TABLE IF EXISTS downtime_events;
CREATE TABLE downtime_events (event_id varchar(64) PRIMARY KEY, area varchar(16) NOT NULL,
 equipment_code varchar(64) NOT NULL, started_at_utc datetime NOT NULL, ended_at_utc datetime,
 reason_code varchar(32) NOT NULL, reason_text varchar(255), equipment_stop_min decimal(8,1), production_stop_min decimal(8,1));
